script.text:

function load$GridReport$(g) {g.add_onRender(on$GridReport$Render); g.add_commandEvent(on$GridReport$ExecuteCommand); }
function dispose$GridReport$(g) {try {g.remove_onRender(on$GridReport$Render);} catch (ex) {}; try {g.remove_commandEven(on$GridReport$ExecuteCommand)} catch (ex) {};}
function on$GridReport$ExecuteCommand(sender, e) {
	var g = sender, action = e.type.Action;
	switch (action) {
		case 'View':
			e.type.cancelEvent = true;
			var tk = g._getItemValue(g._activeRow, g._getColumnOrder('tk'));
			var ma_vv = g._getItemValue(g._activeRow, g._getColumnOrder('ma_vv'));
			var ma_td3 = g._getItemValue(g._activeRow, g._getColumnOrder('ma_td3'));
			var ma_phi = g._getItemValue(g._activeRow, g._getColumnOrder('ma_phi'));
			if (!ma_vv && !ma_td3) break;
			var a = g._queryFilterString.split(String.fromCharCode(253));
			g._$result = [tk, ma_vv, ma_td3, ma_phi, a[1], a[2], a[3], a[6] ]
			//ngay1, ngay2, ma_dvcs, tk, vu_viec_me, mau_bc
			g._navigate(g._activeCell, '&Url;');
			break;
		default:
			break;
	}
}
function passQueryParameters(g) {&Parameter;
	var a = [
		{Name: 'tk', Value: g._$result[0]},
		{Name: 'ma_vv', Value: g._$result[1]},
		{Name: 'ma_td3', Value: g._$result[2]},
		{Name: 'ma_phi', Value: g._$result[3]},
		{Name: 'ngay_ht1', Value: formaDate(g._$result[4])},
		{Name: 'ngay_ht2', Value: formaDate(g._$result[5])},
		{Name: 'ma_dvcs', Value: g._$result[6]},
		{Name: 'mau_bc', Value: g._$result[7]}
	];
	var session = {Memvar: a, Script: 'this._convection = true;'&Session;};
	g._passParameter(session);

}
function formaDate(dateString) {
	return new Date( dateString.substring(0, 4), dateString.substring(4, 6) - 1, dateString.substring(6, 8)); 
}
function on$GridReport$Render(sender, eventArgs) {
	var g = eventArgs.grid;  
	if (g._hiddenFields) {
		var a = g._hiddenFields, h = '';
		for (var i = 0; i < a.length; i++) {
			setGridHiddenFields(g, a[i].Fields, a[i].Value);
			if (a[i].Value) h += (h == '' ? '' : ',') + a[i].Fields;
		}
		g._externalHiddenFields = h;
	}
	setColorWithCondition(g, 'sysorder', '3', '', 'bold', '');
	setColorWithCondition(g, 'sysorder', '4', '', 'bold', '');
}
function setGridHiddenFields(g, c, v) {
	var a = c.split(',');
	for (var i = 0; i < a.length; i++) {
		var l = g._getColumnOrder($func.trim(a[i]));
		if (l != -1) g._setColumnVisible(l, !v);
	}
}

function setColorWithCondition(g, field, condition, color, bold, italic) {
		var iC	
		try {iC = g._getColumnOrder(field);				
			var r = g._rowCount;
			var i;
			for (i = 1; i <= r; i++) {
					if (g._getItemValue(i, iC) == condition) {
							setColor4Row(g, i, color);
							setFont4Row(g, i, bold, italic);
					}
			}
		}
		catch (err){}
}

function setColor4Row(g, rNumber, color) {
		var c = g._columnCount;
		var i;
		var o;
		for (i = 1; i <= c; i++) {
				o = g._getItem(rNumber, i);
				if (color != '') {
					//	o.style.color = color;
						$get(g.get_id()+ '_gridCell_' + rNumber.toString() + '.' +  i.toString()).style.backgroundColor = color;

					//	o.style.backgroundColor = color;

				}
		}
}

function setFont4Row(g, rNumber, bold, italic) {
		var c = g._columnCount;
		var i;
		var o;
		for (i = 1; i <= c; i++) {
				o = g._getItem(rNumber, i);
				if (bold != '') {
						o.style.fontWeight = bold;
				}
				if (italic != '') {
						o.style.fontStyle = italic;
				}
		}
}

function beforeDrillDownWithCondition(g) {g._args.cancelEvent = (g._getItemValue(g._activeRow, g._getColumnOrder('systotal')) == 0);}
function formatDateView(c) {return String.format('{0}/{1}/{2}', c.substring(6, 8), c.substring(4, 6), c.substring(0, 4));}
